package io.knowledgebrain.notification;
import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.notification.group-review.enabled",havingValue="true") @RequestMapping("/api/groups/{groupId}")
final class GroupReviewController {
 private final GroupReviewStore store;private final GroupReviewAuthority authority;private final String origin;private final MeterRegistry metrics;
 GroupReviewController(GroupReviewStore store,GroupReviewAuthority authority,@Value("${brain.notification.browser-origin}")String origin,MeterRegistry metrics){this.store=store;this.authority=authority;this.origin=origin;this.metrics=metrics;}
 private GroupReviewStore.Access auth(String group,HttpServletRequest r,boolean write){if(!r.isSecure())throw NotificationController.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);token=c.getValue();}return authority.authorize(NotificationStore.id(group),token,NotificationController.parent(r));}
 private static long expected(HttpServletRequest r,String prefix,boolean zero){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED);if(h.size()!=1||!h.getFirst().matches("\""+prefix+(zero?"(0|[1-9][0-9]{0,18})":"[1-9][0-9]{0,18}")+"\""))throw NotificationController.bad();try{return Long.parseLong(h.getFirst().substring(prefix.length()+1,h.getFirst().length()-1));}catch(NumberFormatException ex){throw NotificationController.bad();}}
 private static boolean bool(HttpServletRequest r,String name)throws java.io.IOException{if(!"application/json".equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE);var b=r.getInputStream().readNBytes(1025);if(b.length>1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);try{var j=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build().readTree(b);if(j==null||!j.isObject()||j.size()!=1||!j.path(name).isBoolean())throw NotificationController.bad();return j.path(name).asBoolean();}catch(tools.jackson.core.JacksonException ex){throw NotificationController.bad();}}
 private static <T>ResponseEntity<T> response(T body,String etag){var b=ResponseEntity.ok().cacheControl(CacheControl.noStore());if(etag!=null)b.eTag(etag);return b.body(body);}
 @GetMapping("/notification-preference") ResponseEntity<?> preference(@PathVariable String groupId,HttpServletRequest r){NotificationController.parameters(r,Set.of());var p=store.preference(auth(groupId,r,false));return response(p,"\"gnp"+p.version()+"\"");}
 @PutMapping("/notification-preference") ResponseEntity<?> preferenceChange(@PathVariable String groupId,HttpServletRequest r)throws java.io.IOException{NotificationController.parameters(r,Set.of());var a=auth(groupId,r,true);long expected=expected(r,"gnp",true);boolean enabled=bool(r,"enabled");var p=store.preference(a,expected,enabled,NotificationController.parent(r).substring(3,35));metrics.counter("brain.notification.group-review.changes","type","preference").increment();return response(p,"\"gnp"+p.version()+"\"");}
 @GetMapping("/notification-preference/revisions") ResponseEntity<?> preferenceHistory(@PathVariable String groupId,HttpServletRequest r){NotificationController.parameters(r,Set.of("before","limit"));return response(store.preferenceHistory(auth(groupId,r,false),NotificationController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)NotificationController.number(r.getParameter("limit"),5,10)),null);}
 @GetMapping("/notifications") ResponseEntity<?> list(@PathVariable String groupId,HttpServletRequest r){NotificationController.parameters(r,Set.of("state","read","after","limit"));var a=auth(groupId,r,false);metrics.counter("brain.notification.group-review.reads","type","catalog").increment();return response(store.list(a,Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE"),Optional.ofNullable(r.getParameter("read")).orElse("ALL"),r.getParameter("after"),(int)NotificationController.number(r.getParameter("limit"),20,100)),null);}
 @GetMapping("/notifications/{id}") ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String id,HttpServletRequest r){NotificationController.parameters(r,Set.of());var n=store.get(auth(groupId,r,false),NotificationStore.id(id));return response(n,"\"gn"+n.version()+"\"");}
 @PutMapping("/notifications/{id}") ResponseEntity<?> read(@PathVariable String groupId,@PathVariable String id,HttpServletRequest r)throws java.io.IOException{NotificationController.parameters(r,Set.of());var a=auth(groupId,r,true);long expected=expected(r,"gn",false);var n=store.change(a,NotificationStore.id(id),expected,bool(r,"read"),false,NotificationController.parent(r).substring(3,35));return response(n,"\"gn"+n.version()+"\"");}
 @DeleteMapping("/notifications/{id}") ResponseEntity<?> retire(@PathVariable String groupId,@PathVariable String id,HttpServletRequest r){NotificationController.parameters(r,Set.of());var n=store.change(auth(groupId,r,true),NotificationStore.id(id),expected(r,"gn",false),null,true,NotificationController.parent(r).substring(3,35));return response(n,"\"gn"+n.version()+"\"");}
 @GetMapping("/notifications/{id}/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String id,HttpServletRequest r){NotificationController.parameters(r,Set.of("before","limit"));return response(store.history(auth(groupId,r,false),NotificationStore.id(id),NotificationController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)NotificationController.number(r.getParameter("limit"),5,10)),null);}
}
